sys_security_acl.script:
// Allow managers to update status for their direct reports
var user = new GlideRecordSecure('sys_user');
if (user.get(current.employee)) {
    // Manager can update status
    if (user.manager == gs.getUserID()) {
        answer = true;
    }
}

// HR admins can update any status
if (gs.hasRole('x_1800027_leve_sys.leave_hr_admin')) {
    answer = true;
}

answer = false;
